import{ref,reactive}from"vue";import{defineStore}from"pinia";import axios from"axios";import{useCustomStore}from"./customStore";export const useStudentStore=defineStore("student",()=>{const apiUrl=import.meta.env.VITE_APP_API_URL,customStore=useCustomStore(),isLoading=ref(!1),data=ref([]),fetchStudentHandler=async()=>{const res=await axios.get(apiUrl+"/fetchStudent");data.value=res.data.result};return fetchStudentHandler(),{apiUrl:apiUrl,isLoading:isLoading,fetchStudentHandler:fetchStudentHandler,data:data}});